import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../hooks/useToast';
import Navbar from '../components/Navbar';
import Sidebar from '../components/Sidebar';
import BookCard from '../components/BookCard';
import IssuedBookCard from '../components/IssuedBookCard';
import * as api from '../api';

// ─── Sub-views ──────────────────────────────────────────────────

function Welcome({ user, books, issues, requests }) {
  return (
    <div>
      <div style={{ textAlign:'center', padding:'2rem 0 3rem' }}>
        <div style={{ fontSize:'5rem', marginBottom:'1rem' }}>📚</div>
        <h2 className="title-font" style={{ fontSize:'3rem', marginBottom:'0.5rem' }}>Welcome back, {user.name.split(' ')[0]}!</h2>
        <p style={{ opacity:0.7 }}>Role: <span style={{ color:'#93c5fd', fontWeight:600 }}>{user.role}</span></p>
      </div>

      <div className="section-grid-auto" style={{ marginBottom:'2rem' }}>
        {[
          { icon:'📖', val: books.length, label:'Total Books', sub:`${books.reduce((a,b)=>a+b.availableCopies,0)} available` },
          { icon:'📤', val: issues.filter(i=>!i.returned).length, label:'Books Issued', sub:'Active loans' },
          { icon:'⏳', val: requests.length, label:'Pending Requests', sub:'Awaiting approval' },
        ].map(s => (
          <div key={s.label} className="glass card-hover" style={{ borderRadius:'1.25rem', padding:'1.5rem', textAlign:'center' }}>
            <div style={{ fontSize:'2.5rem', marginBottom:'0.5rem' }}>{s.icon}</div>
            <div style={{ fontSize:'2.5rem', fontWeight:700 }}>{s.val}</div>
            <div style={{ fontWeight:600, opacity:0.9 }}>{s.label}</div>
            <div style={{ fontSize:'0.75rem', opacity:0.6, marginTop:'0.25rem' }}>{s.sub}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

function Profile({ user, myIssues, myRequests }) {
  return (
    <div className="split-layout">
      <div className="glass" style={{ borderRadius:'1.5rem', padding:'2rem' }}>
        <div style={{ display:'flex', alignItems:'center', gap:'1.5rem', marginBottom:'2rem' }}>
          <div style={{ width:80, height:80, borderRadius:'1.25rem', background:'linear-gradient(135deg,#3b82f6,#8b5cf6,#ec4899)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:'2.5rem', flexShrink:0 }}>👤</div>
          <div>
            <h3 className="title-font" style={{ fontSize:'2rem' }}>{user.name}</h3>
            <p style={{ color:'#93c5fd', fontWeight:600 }}>@{user.username}</p>
            <p style={{ opacity:0.7, fontSize:'0.9rem' }}>Role: <span style={{ color:'#c4b5fd', fontWeight:600 }}>{user.role}</span></p>
          </div>
        </div>
        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit,minmax(220px,1fr))', gap:'1rem' }}>
          {[['Full Name',user.name],['Username',user.username],['Email',user.email],['Roll No',user.rollno||'—'],['Role',user.role],['User ID',user._id?.slice(-8)]].map(([k,v]) => (
            <div key={k} style={{ background:'rgba(255,255,255,0.06)', borderRadius:'0.875rem', padding:'1rem', border:'1px solid rgba(255,255,255,0.1)' }}>
              <p style={{ fontSize:'0.65rem', textTransform:'uppercase', opacity:0.6, fontWeight:700, marginBottom:'0.25rem' }}>{k}</p>
              <p style={{ fontWeight:600 }}>{v}</p>
            </div>
          ))}
        </div>
      </div>

      <div className="stack-grid">
        <div className="glass" style={{ borderRadius:'1.5rem', padding:'1.5rem' }}>
          <h4 className="title-font" style={{ fontSize:'1.3rem', marginBottom:'1rem' }}>📊 Stats</h4>
          {[
            { icon:'📚', val: myIssues.filter(i=>!i.returned).length, label:'Currently Borrowed' },
            { icon:'✅', val: myIssues.filter(i=>i.returned).length, label:'Returned' },
            { icon:'⏳', val: myRequests.length, label:'Pending Requests' },
          ].map(s => (
            <div key={s.label} style={{ display:'flex', justifyContent:'space-between', alignItems:'center', padding:'0.75rem', background:'rgba(255,255,255,0.06)', borderRadius:'0.75rem', marginBottom:'0.5rem' }}>
              <span style={{ fontSize:'0.85rem' }}>{s.icon} {s.label}</span>
              <span style={{ fontWeight:700, fontSize:'1.2rem' }}>{s.val}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function SearchCatalog({ user }) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [searched, setSearched] = useState(false);
  const { showToast, ToastEl } = useToast();

  const search = async () => {
    if (!query.trim()) return;
    try {
      const res = await api.getBooks(query);
      setResults(res.data);
      setSearched(true);
    } catch { showToast('Search failed', true); }
  };

  const handleAction = async (action, book) => {
    if (action === 'request') {
      try {
        await api.makeRequest(book._id);
        showToast('Request submitted!');
      } catch (err) { showToast(err.response?.data?.message || 'Request failed', true); }
    }
  };

  const canRequest = user.role === 'Student' || user.role === 'Faculty';

  return (
    <div>
      {ToastEl}
      <div className="glass" style={{ borderRadius:'1.5rem', padding:'2rem', marginBottom:'1.5rem' }}>
        <div className="search-bar">
          <input className="input-field" placeholder="Search by title, author, or subject..." value={query}
            onChange={e => setQuery(e.target.value)} onKeyDown={e => e.key==='Enter' && search()} style={{ flex:1, fontSize:'1rem', padding:'1rem 1.25rem' }} />
          <button onClick={search} className="btn-primary" style={{ padding:'1rem 1.5rem', fontSize:'1rem' }}>🔍</button>
        </div>
        <div style={{ display:'flex', gap:'0.75rem', marginTop:'1rem', flexWrap:'wrap' }}>
          <span style={{ opacity:0.6, fontSize:'0.8rem', alignSelf:'center' }}>Quick:</span>
          {['Computer Science','Database','AI','Algorithms'].map(t => (
            <button key={t} onClick={() => { setQuery(t); setTimeout(search, 50); }} className="btn-ghost" style={{ padding:'0.35rem 0.875rem', fontSize:'0.78rem' }}>{t}</button>
          ))}
        </div>
      </div>

      {searched ? (
        results.length > 0
          ? <div className="card-grid">
              {results.map(b => <BookCard key={b._id} book={b} actionType={canRequest ? 'request' : null} onAction={handleAction} />)}
            </div>
          : <p style={{ textAlign:'center', opacity:0.6, padding:'3rem' }}>No books found for "{query}"</p>
      ) : (
        <div style={{ textAlign:'center', padding:'4rem', opacity:0.5 }}>
          <div style={{ fontSize:'4rem', marginBottom:'1rem' }}>📚</div>
          <p>Enter a search term to find books</p>
        </div>
      )}
    </div>
  );
}

function MyBooks({ user }) {
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.getMyBooks().then(r => setBooks(r.data)).finally(() => setLoading(false));
  }, []);

  if (loading) return <p style={{ textAlign:'center', padding:'3rem', opacity:0.6 }}>Loading...</p>;

  return (
    <div>
      <h3 style={{ fontSize:'1.25rem', fontWeight:700, marginBottom:'1rem' }}>📘 Currently Borrowed ({books.length})</h3>
      {books.length === 0
        ? <p style={{ textAlign:'center', opacity:0.6, padding:'3rem' }}>No books currently borrowed</p>
        : books.map(item => <IssuedBookCard key={item._id} item={item} showReturn={false} />)
      }
    </div>
  );
}

export { Welcome, Profile, SearchCatalog, MyBooks };
